+constexpr uint32_t GENERAL_SORT_CAPACITY = TOPK * 2U;
+constexpr uint32_t GENERAL_ROUTE_ALIGN = 8U;
+constexpr uint32_t FIRST_DECODE_LIST_CAPACITY = CAPACITY * 2U;
