+        uint32_t unionCount = 0U;
+        bool overflow = false;
+        bool capturedOccurrences = false;
+        if (useMaturePairUnion) {
+            const uint64_t pairBase =
+                static_cast<uint64_t>(batch) * CAPACITY;
