+    if (cubeMSize > maxMSize) {
+        cubeMSize = maxMSize;
+    }
+    mmResUbSize_ = sInnerSizeAlign_ * FusedScatterCopySparseFlashAttentionAlign(cubeMSize, 16U);
+    bmm2ResUbSize_ = headDimAlign_ * FusedScatterCopySparseFlashAttentionAlign(cubeMSize, 16U);
