+    OPS_LOG_E(opName_, "Tensor %s only supports dtype %s, but got %s",
+        name.c_str(), oss.str().c_str(), FusedScatterCopySparseFlashAttentionDataTypeToSerialString(actualDtype).c_str());
+}
