+uint32_t FusedScatterCopySparseFlashAttentionTilingCheck::GetTypeSize(ge::DataType dtype) const
+{
+    uint32_t typeSize = NUM_BYTES_FLOAT16;
+    switch (dtype) {
+        case ge::DT_FLOAT16:
+            typeSize = NUM_BYTES_FLOAT16;
+            break;
+        case ge::DT_BF16:
+            typeSize = NUM_BYTES_BF16;
+            break;
+        default:
+            typeSize = NUM_BYTES_FLOAT16;
