+template <typename SFAT>
+__aicore__ inline void SFAMatmulService<SFAT>::CopyGmToL1(LocalTensor<KV_T> &l1Tensor,
+                                                                 GlobalTensor<KV_T> &gmSrcTensor, uint32_t srcN,
+                                                                 uint32_t srcD, uint32_t srcDstride)
+{
