+    int32_t copyCountIndex_ = -1;
+    int32_t cachedCopyCount_ = 0;
+    int64_t addressRequest_ = -1;
+    int64_t hbmTableRow_ = 0;
+    int64_t dramTableRow_ = 0;
+
+    // ================================Local Buffer====================================
+    TBuf<> inputBuff1;            // 32K
+    TBuf<> inputBuff2;            // 16K
+    TBuf<> outputBuff1;           // 32K
+    TBuf<> outputBuff2;           // 4K
+
+    TBuf<> tmpBuff1;              // 32K
