+
+    TBuf<> nValueBuff;
+    TBuf<> cofValueBuff;
+    TBuf<> aMlaSumBuff;
+    TBuf<> softmaxMaxBuff;        // PRE_LOAD_NUM * 2K
+    TBuf<> softmaxExpBuff;        // PRE_LOAD_NUM * 2K
+    TBuf<> softmaxSumBuff;        // PRE_LOAD_NUM * 2K
+    TBuf<> softmaxMaxDefaultBuff; // 2K
+    TBuf<> softmaxSumDefaultBuff; // 2K
+
+    LocalTensor<T> softmaxMaxDefaultUb;
